      "content": "{\n  \"name\": \"dsh-agent-team-gui\",\n  \"version\": \"1.3.0\",\n  \"description\": \"Persistent multi-model squads for DeepSeek Harness with durable orchestration, DAG workflows, run history, and provider-reported token usage\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib/index.js\",\n    \"lib/client.js\",\n    \"lib/client.js.map\",\n    \"lib/types/index.d.ts\",\n    \"lib/types/client/index.d.ts\",\n    \"lib/types/**/*.d.ts\",\n    \"lib/types/**/*.d.ts.map\",\n    \"cordis.patch.yml\",\n    \"assets/*.png\",\n    \"examples/**/*.json\",\n    \"docs/**/*.md\",\n    \"CHANGELOG.md\",\n    \"CODE_OF_CONDUCT.md\",\n    \"CONTRIBUTING.md\",\n    \"SECURITY.md\",\n    \"README-zh.md\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-renderer\",\n        \"@deepseek-ai/dsh-client-ui-session\",\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-client-ui-settings\"\n      ]\n    }\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"dsh-plugins\",\n    \"deepseek-harness\",\n    \"deepseek-harness-plugin\",\n    \"agent\",\n    \"multi-agent\",\n    \"multi-model\",\n    \"orchestration\",\n    \"token-usage\",\n    \"agent-team\"\n  ],\n  \"license\": \"MIT\",\n  \"author\": \"leizihao and dsh-agent-team-gui contributors\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/toolclub/dsh-agent-team-gui.git\"\n  },\n  \"homepage\": \"https://github.com/toolclub/dsh-agent-team-gui#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/toolclub/dsh-agent-team-gui/issues\"\n  },\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\"\n  },\n  \"packageManager\": \"pnpm@9.15.4\",\n  \"scripts\": {\n    \"build\": \"node scripts/quality/clean-build.mjs && tsdown --config tsdown.config.ts && tsc -p tsconfig.host.json --pretty false && tsc -p tsconfig.client.json --pretty false\",\n    \"check:whitespace\": \"node scripts/quality/git-whitespace.mjs\",\n    \"prepare\": \"pnpm run build\",\n    \"prepack\": \"pnpm run build\",\n    \"typecheck\": \"tsc -p tsconfig.host.json --noEmit --pretty false && tsc -p tsconfig.client.json --noEmit --pretty false && tsc -p tsconfig.test.json --pretty false && tsc -p tsconfig.client-test.json --pretty false\",\n    \"typecheck:host\": \"tsc -p tsconfig.host.json --noEmit --pretty false && tsc -p tsconfig.test.json --pretty false\",\n    \"typecheck:client\": \"tsc -p tsconfig.client.json --noEmit --pretty false && tsc -p tsconfig.client-test.json --pretty false\",\n    \"test\": \"pnpm run test:host && pnpm run test:client\",\n    \"test:host\": \"vitest run --config vitest.host.config.ts\",\n    \"test:client\": \"vitest run --config vitest.client.config.ts\",\n    \"audit:pack\": \"node scripts/quality/pack-audit.mjs\",\n    \"smoke:install\": \"node scripts/quality/dsh-smoke.mjs\",\n    \"smoke:browser\": \"node scripts/quality/browser-smoke.mjs\",\n    \"capture:readme\": \"node scripts/quality/capture-readme.mjs\",\n    \"quality:doctor\": \"node scripts/quality/doctor.mjs\",\n    \"preflight\": \"node scripts/quality/release-preflight.mjs\"\n  },\n  \"dependencies\": {\n    \"react\": \"^18.2.0\",\n    \"zod\": \"^4.4.3\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.2\",\n    \"@deepseek-ai/dsh-api-session-controller\": \">=0.1.5-rc.1 <0.1.6-0\",\n    \"@deepseek-ai/dsh-agent\": \">=0.1.5-rc.1 <0.1.6-0\",\n    \"@deepseek-ai/dsh-brand\": \">=0.1.5-rc.1 <0.1.6-0\",\n    \"@deepseek-ai/dsh-client-connection\": \">=0.1.5-rc.1 <0.1.6-0\",\n    \"@deepseek-ai/dsh-client-locale\": \">=0.1.5-rc.1 <0.1.6-0\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \">=0.1.5-rc.1 <0.1.6-0\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \">=0.1.5-rc.1 <0.1.6-0\",\n    \"@deepseek-ai/dsh-client-ui-session\": \">=0.1.5-rc.1 <0.1.6-0\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \">=0.1.5-rc.1 <0.1.6-0\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \">=0.1.5-rc.1 <0.1.6-0\",\n    \"@deepseek-ai/dsh-jobs\": \">=0.1.5-rc.1 <0.1.6-0\",\n    \"@deepseek-ai/dsh-llm\": \">=0.1.5-rc.1 <0.1.6-0\",\n    \"@deepseek-ai/dsh-session\": \">=0.1.5-rc.1 <0.1.6-0\",\n    \"@deepseek-ai/dsh-storage\": \">=0.1.5-rc.1 <0.1.6-0\",\n    \"@deepseek-ai/dsh-storage-domain\": \">=0.1.5-rc.1 <0.1.6-0\",\n    \"@deepseek-ai/dsh-subagent\": \">=0.1.5-rc.1 <0.1.6-0\",\n    \"@deepseek-ai/dsh-system-prompt\": \">=0.1.5-rc.1 <0.1.6-0\",\n    \"@deepseek-ai/dsh-tools\": \">=0.1.5-rc.1 <0.1.6-0\",\n    \"@deepseek-ai/dsh-util-values\": \">=0.1.5-rc.1 <0.1.6-0\",\n    \"@deepseek-ai/schemastery\": \"^3.18.2\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-jobs\": {\n      \"optional\": true\n    }\n  },\n  \"devDependencies\": {\n    \"@axe-core/playwright\": \"^4.10.2\",\n    \"@deepseek-ai/cordis\": \"^4.0.2\",\n    \"@deepseek-ai/dsh-api-session-controller\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-attachment\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-agent\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-atomic-write\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-brand\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-client-connection\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-client-store\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-session\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-code-runtime\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-compaction\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-commands\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-invariants\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-jobs\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-llm\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-scope\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-session\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-session-projection\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-storage\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-storage-domain\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-subagent\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-system-prompt\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-timeout\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-tools\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-util-values\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/dsh-user-approval\": \"0.1.5-rc.2\",\n    \"@deepseek-ai/schemastery\": \"^3.18.2\",\n    \"@testing-library/jest-dom\": \"^7.0.1\",\n    \"@testing-library/react\": \"^16.3.0\",\n    \"@testing-library/user-event\": \"^14.6.1\",\n    \"@types/node\": \"^24.0.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"~18.3.1\",\n    \"dsh-plugin-doctor\": \"0.1.0\",\n    \"happy-dom\": \"^20.11.2\",\n    \"playwright\": \"^1.62.1\",\n    \"react-dom\": \"^18.2.0\",\n    \"tsdown\": \"^0.22.14\",\n    \"typescript\": \"^7.0.2\",\n    \"vitest\": \"^4.1.10\",\n    \"@deepseek-ai/cordis-plugin-loader\": \"^1.0.3\",\n    \"@deepseek-ai/cordis-plugin-include\": \"^1.0.7\"\n  }\n}\n"
